package com.ne.business.dflq.can.service;

import com.ne.business.dflq.can.config.CosConfig;
import com.ne.business.dflq.can.entity.vo.CanRecordFileVo;
import com.ne.business.dflq.can.enums.ConvertStatusEnum;
import com.ne.business.dflq.can.utils.CosFileDownloader;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.apache.poi.common.usermodel.HyperlinkType;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.springframework.stereotype.Service;
import org.springframework.util.CollectionUtils;

import javax.servlet.http.HttpServletResponse;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.net.URLEncoder;
import java.text.SimpleDateFormat;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

/**
 * 专用导出Excel文件服务层
 *
 * @author weihong
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class ExcelExportService {

    private final CosConfig cosConfig;

    /**
     * 导出Excel + ASC文件压缩包
     * 单个文件和多个文件统一走此方法，生成zip压缩包返回
     * zip内包含：一个Excel文件（所有记录在一个sheet中）+ 对应的ASC文件
     *
     * @param dataList 数据列表
     * @param fileName 压缩包文件名（不含扩展名）
     * @param response HTTP响应
     */
    public void exportExcelWithAscFiles(List<CanRecordFileVo> dataList, String fileName,
                                         HttpServletResponse response) throws IOException {
        if (CollectionUtils.isEmpty(dataList)) {
            throw new IllegalArgumentException("数据列表不能为空");
        }

        // 先在内存中构建完整zip，确保无异常后再写入response
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zipOut = new ZipOutputStream(baos)) {
            // 生成Excel并写入zip
            Workbook workbook = createExcelWorkbook(dataList);
            ZipEntry excelEntry = new ZipEntry(fileName + ".xlsx");
            zipOut.putNextEntry(excelEntry);
            workbook.write(zipOut);
            workbook.close();
            zipOut.closeEntry();

            // 下载ASC文件并写入zip
            for (CanRecordFileVo data : dataList) {
                if (data.getConvertStatus() != null && data.getConvertStatus() == ConvertStatusEnum.CONVERTED.getCode()
                        && data.getConvertFileName() != null && !data.getConvertFileName().isEmpty()) {
                    try {
                        String cosKey = cosConfig.getConvertedDir() + data.getConvertFileName();
                        log.info("下载ASC文件: bucket={}, key={}", cosConfig.getBucketName(), cosKey);
                        byte[] ascData = CosFileDownloader.downloadFromCos(cosConfig.getBucketName(), cosKey);

                        ZipEntry ascEntry = new ZipEntry(data.getConvertFileName());
                        zipOut.putNextEntry(ascEntry);
                        zipOut.write(ascData);
                        zipOut.closeEntry();
                        log.info("ASC文件写入zip成功: {}", data.getConvertFileName());
                    } catch (Exception e) {
                        log.error("下载ASC文件失败，跳过: convertFileName={}, 错误: {}",
                                data.getConvertFileName(), e.getMessage(), e);
                    }
                }
            }
        }

        // zip构建完成，无异常，设置响应头并以流写入response
        byte[] zipBytes = baos.toByteArray();
        response.setContentType("application/zip");
        response.setHeader("Content-Disposition",
                "attachment;filename=" + URLEncoder.encode(fileName + ".zip", "UTF-8"));
        response.setContentLength(zipBytes.length);
        response.getOutputStream().write(zipBytes);
        response.getOutputStream().flush();
    }

    /**
     * 创建Excel工作簿
     * 表头：任务名称 | 录制文件名 | 开始时间 | 结束时间
     */
    private Workbook createExcelWorkbook(List<CanRecordFileVo> dataList) {
        Workbook workbook = new XSSFWorkbook();
        CreationHelper creationHelper = workbook.getCreationHelper();
        Sheet sheet = workbook.createSheet("录制文件列表");

        // 表头列定义
        String[] headers = {"任务名称", "录制文件名", "开始时间", "结束时间"};

        // 表头样式
        CellStyle headerStyle = workbook.createCellStyle();
        Font headerFont = workbook.createFont();
        headerFont.setBold(true);
        headerStyle.setFont(headerFont);

        // 超链接样式（蓝色下划线）
        CellStyle linkStyle = workbook.createCellStyle();
        Font linkFont = workbook.createFont();
        linkFont.setUnderline(Font.U_SINGLE);
        linkFont.setColor(IndexedColors.BLUE.getIndex());
        linkStyle.setFont(linkFont);

        // 创建表头行
        Row headerRow = sheet.createRow(0);
        for (int i = 0; i < headers.length; i++) {
            Cell cell = headerRow.createCell(i);
            cell.setCellValue(headers[i]);
            cell.setCellStyle(headerStyle);
        }

        // 日期格式
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

        // 创建数据行
        for (int i = 0; i < dataList.size(); i++) {
            CanRecordFileVo data = dataList.get(i);
            Row dataRow = sheet.createRow(i + 1);

            // 任务名称
            dataRow.createCell(0).setCellValue(data.getTaskName() != null ? data.getTaskName() : "");

            // 录制文件名（已转换的文件添加超链接指向zip内的asc文件）
            Cell convertFileCell = dataRow.createCell(1);
            String convertFileName = data.getConvertFileName();
            convertFileCell.setCellValue(convertFileName != null ? convertFileName : "");
            if (convertFileName != null && !convertFileName.isEmpty()
                    && data.getConvertStatus() != null
                    && data.getConvertStatus() == ConvertStatusEnum.CONVERTED.getCode()) {
                Hyperlink hyperlink = creationHelper.createHyperlink(HyperlinkType.FILE);
                hyperlink.setAddress("./" + convertFileName);
                convertFileCell.setHyperlink(hyperlink);
                convertFileCell.setCellStyle(linkStyle);
            }

            // 开始时间
            dataRow.createCell(2).setCellValue(
                    data.getStartTime() != null ? sdf.format(data.getStartTime()) : "");
            // 结束时间
            dataRow.createCell(3).setCellValue(
                    data.getEndTime() != null ? sdf.format(data.getEndTime()) : "");
        }

        // 设置列宽（单位：1/256个字符宽度）
        sheet.setColumnWidth(0, 30 * 256);  // 任务名称
        sheet.setColumnWidth(1, 35 * 256);  // 录制文件名
        sheet.setColumnWidth(2, 22 * 256);  // 开始时间
        sheet.setColumnWidth(3, 22 * 256);  // 结束时间

        return workbook;
    }
}

